// app/api/calls/[roomName]/route.ts — DELETE handler (duration fix)
export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ roomName: string }> }
) {
  try {
    const session = await requireSession();
    const { roomName } = await params;

    const call = await db.query.callHistory.findFirst({
      where: and(
        eq(callHistory.roomName, roomName),
        or(
          eq(callHistory.callerId, session.user.id),
          eq(callHistory.calleeId, session.user.id)
        )
      )
    });

    if (!call) {
      return NextResponse.json({ error: 'Call not found' }, { status: 404 });
    }

    // Safe coercion — Drizzle returns timestamptz as string, not Date
    const toDate = (v: Date | string | null | undefined): Date | null => {
      if (v == null) return null;
      return v instanceof Date ? v : new Date(v);
    };

    const endedAt = new Date();
    const startedAt = toDate(call.startedAt);
    const durationSeconds = startedAt
      ? Math.floor((endedAt.getTime() - startedAt.getTime()) / 1000)
      : 0; // safe fallback if call was never fully joined

    await db
      .update(callHistory)
      .set({
        status: 'completed',
        endedAt,
        durationSeconds,
      })
      .where(eq(callHistory.roomName, roomName));

    // Notify the other participant
    const otherId =
      call.callerId === session.user.id ? call.calleeId : call.callerId;
    if (otherId) {
      await ablyPublish(`user:${otherId}`, 'call_ended', {
        roomName,
        durationSeconds,
      });
    }

    // Delete the LiveKit room
    // await livekitRoomService.deleteRoom(roomName);

    return NextResponse.json({ success: true, durationSeconds });
  } catch (error) {
    console.error('[DELETE /api/calls] Error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

