// lib/utils.ts — add this utility (alongside existing cn() helper)
export const toDate = (
  v: Date | string | null | undefined
): Date | null => {
  if (v == null) return null;
  return v instanceof Date ? v : new Date(v);
};

// hooks/useCallState.ts — coerce on state update
setActiveCall(prev => ({
  ...prev,
  startedAt: toDate(data.startedAt), // never raw string
}));

// components/calls/ActiveCallBadge.tsx — safe elapsed timer
useEffect(() => {
  const interval = setInterval(() => {
    const start = toDate(activeCall?.startedAt);
    if (!start) return;
    setElapsed(Math.floor((Date.now() - start.getTime()) / 1000));
  }, 1000);
  return () => clearInterval(interval);
}, [activeCall?.startedAt]);

